import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"请求生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"backend/request-lifecycle.md","filePath":"backend/request-lifecycle.md","lastUpdated":1794049926000}`),a={name:`backend/request-lifecycle.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="请求生命周期" tabindex="-1">请求生命周期 <a class="header-anchor" href="#请求生命周期" aria-label="Permalink to “请求生命周期”">​</a></h1><p>本页说明一次调用从进入宿主到返回响应所经过的各个阶段，以及 BasicApp 在各阶段贡献的中间件，适用于排查认证、权限与审计问题的后端开发者。</p><p>一个 HTTP 请求先经过宿主的 ASP.NET Core 中间件，再进入 XiHan 内核管道；内核管道分 11 个阶段，每个阶段里有框架内置与各能力包贡献的中间件。gRPC、MCP 与 CloudEvents 的调用从各自的协议适配器进入同一条内核管道，所以租户、权限、事务、审计的行为各协议一致。</p><h2 id="一、asp-net-core-段" tabindex="-1">一、ASP.NET Core 段 <a class="header-anchor" href="#一、asp-net-core-段" aria-label="Permalink to “一、ASP.NET Core 段”">​</a></h2><p><code>BasicAppHost.Map</code> 的顺序：</p><table tabindex="0"><thead><tr><th>顺序</th><th>中间件</th><th>作用</th></tr></thead><tbody><tr><td>1</td><td><code>UseForwardedHeaders</code></td><td>还原代理转发的客户端地址、协议与主机（<code>BasicApp:ForwardedHeaders</code>，缺省只信本机回环）；之后的日志、会话、节流与访问策略拿到的都是还原后的地址</td></tr><tr><td>2</td><td><code>ResponseSecurityHeadersMiddleware</code></td><td>一律加 <code>X-Content-Type-Options: nosniff</code></td></tr><tr><td>3</td><td><code>UseCors</code></td><td>只在 <code>BasicApp:Cors</code> 配了来源时启用；维护期间的 503 也带跨域头</td></tr><tr><td>4</td><td><code>MaintenanceModeMiddleware</code></td><td>别的节点升级共享库期间返回 503（<code>RUNTIME_UNAVAILABLE_003</code>，带 <code>Retry-After</code>）；放行 <code>/health</code> 与 <code>/.well-known/</code></td></tr><tr><td>5</td><td><code>UseAuthentication</code> / <code>UseAuthorization</code></td><td>只服务绕过内核管道的端点（实时 Hub）：XiHan 方案按 <code>Security.Jwt</code> 的同一套参数校验，令牌只在 <code>/hubs</code> 下从查询串读</td></tr><tr><td>6</td><td><code>UseOpenApiRequestBuffer</code></td><td>为签名开放接口留下请求体原文（验签要原文，加密的要先解密）</td></tr><tr><td>7</td><td><code>UseXiHan()</code></td><td>进入内核管道</td></tr></tbody></table><p>绕过内核管道的端点（<code>BypassXiHanPipeline()</code>）：Scalar 页面、根路径自述、实时 Hub、OAuth 2.0 / OIDC 端点、第三方登录的跳转与回调、Telegram Webhook。它们没有调用上下文，自己处理认证与错误。</p><h2 id="二、内核管道" tabindex="-1">二、内核管道 <a class="header-anchor" href="#二、内核管道" aria-label="Permalink to “二、内核管道”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ingress → Observe → Resilience → Authenticate → Tenant → Authorize → Validate → Idempotency → Transaction → Handle → Egress</span></span></code></pre></div><table tabindex="0"><thead><tr><th>阶段</th><th>框架内置</th><th>BasicApp 贡献</th></tr></thead><tbody><tr><td>Ingress</td><td>协议归一化、大小限制、构造调用上下文与调用来源（协议、目标、远端地址、User-Agent）</td><td>—</td></tr><tr><td>Observe</td><td>链路、日志、指标；Full Profile 的 <code>AuditMiddleware</code>（<code>XiHan:Auditing:Selection = None</code>，由 Auditing 显式声明要审计的操作）</td><td><code>AuditLogMiddleware</code>（Auditing，排在框架审计之内）：标了 <code>audited</code> 的操作声明审计动作并补耗时、登录名、会话、客户端信息；按结果写访问、异常日志，以及调用里登记的登录、开放接口、条件命中日志，权限变更日志与数据变更只在成功时写</td></tr><tr><td>Resilience</td><td>截止时间（<code>xihan-deadline</code>）、按操作 ID 的限流、并发上限与熔断（<code>XiHan:Kernel:Resilience</code>）</td><td>—</td></tr><tr><td>Authenticate</td><td>JWT 校验（HS256）</td><td><code>SessionGateMiddleware</code>（Identity，排在 JWT 之后）：令牌带 <code>sid</code> 时核对会话有效，已吊销、已过期或用户不正常 → <code>IDENTITY_DENIED_001</code>；锁定的会话只放行 <code>auth.unlock</code> 与 <code>auth.logout</code>（强制改密锁另放行 <code>profile.change-password</code>），其余 <code>IDENTITY_DENIED_002</code><br><code>RequestSigningMiddleware</code>（OpenPlatform，只对 <code>open.*</code>）：验签、防重放、解密，并登记开放接口日志</td></tr><tr><td>Tenant</td><td>从令牌 <code>tenant</code> 声明（及内部调用的 Baggage）解析租户</td><td><code>AccessPolicyMiddleware</code>（Access，排在租户解析之后，只管 HTTP、gRPC、MCP 入站）：先看登录失败自动封禁（503 <code>ACCESS_UNAVAILABLE_001</code>），再求平台层、租户层访问策略，拒绝 → 403 <code>ACCESS_DENIED_004</code>，命中都记条件命中；判定本身出错时放行并记警告</td></tr><tr><td>Authorize</td><td>按操作声明的权限码 / 策略判定；<code>PermissionChecker</code> 查授予存储与 <code>IPermissionGrantSource</code>，再经各 <code>IPermissionFilter</code> 收窄</td><td>Access 登记的 <code>AccessGrantSource</code>（继承、委托）、<code>AccessPermissionFilter</code>（Deny、有效期、作用侧）、<code>EditionPermissionFilter</code>（套餐门控）<br><code>PermissionConditionMiddleware</code>（排在框架授权之后）：持有的权限码挂了条件时按请求属性精确判定</td></tr><tr><td>Validate</td><td>按操作请求的 JSON Schema 校验载荷，再执行 <code>IValidatableObject</code>；失败带字段级 <code>errors</code></td><td>—</td></tr><tr><td>Idempotency</td><td>幂等键去重（<code>XiHan:Caching:Idempotency</code>）</td><td>—</td></tr><tr><td>Transaction</td><td>工作单元：成功提交、失败回滚；提交前把领域事件写进发件箱</td><td>阶段开头、工作单元之外：<code>CacheInvalidationMiddleware</code>（Runtime，调用里记下的缓存失效在提交或回滚之后才删键）、<code>RealtimeDispatchMiddleware</code>（Realtime，调用里的推送先暂存，提交且成功后才发出）、<code>PublishProgressMiddleware</code>（Notification，通知发布的开始与失败立即推给发布人）、<code>AiProviderCatalogMiddleware</code>（AI，提供商写入提交后重载目录）<br><code>AuditorStampMiddleware</code>（Runtime）：把当前主体 ID 放进异步本地值，SqlSugar 回调据此填 <code>CreatedBy</code> / <code>ModifiedBy</code> / <code>DeletedBy</code></td></tr><tr><td>Handle</td><td>调用操作的 <code>HandleAsync</code></td><td><code>FieldSecurityMiddleware</code>（Access，工作单元之内）：对绑定了字段安全的操作，受保护的字段不能筛选、排序（<code>ACCESS_DENIED_006</code>），只读字段不能填、不能改（<code>ACCESS_DENIED_007</code>）；成功响应编码前再由响应过滤器打码。数据范围在各包的查询处显式套用</td></tr><tr><td>Egress</td><td>结果与错误翻译：错误码 → 状态码，消息键按调用方区域翻译成 <code>detail</code></td><td>—</td></tr></tbody></table><p>用 <code>dotnet run --project backend/src/XiHan.BasicApp.Host -- pipeline</code> 可以打印实际的中间件次序。同阶段的中间件按清单 ID 排序，跨包的先后由 <code>context.Pipeline.After&lt;,&gt;()</code> / <code>Before&lt;,&gt;()</code> 显式声明。</p><h2 id="三、典型路径" tabindex="-1">三、典型路径 <a class="header-anchor" href="#三、典型路径" aria-label="Permalink to “三、典型路径”">​</a></h2><h3 id="未认证与会话失效" tabindex="-1">未认证与会话失效 <a class="header-anchor" href="#未认证与会话失效" aria-label="Permalink to “未认证与会话失效”">​</a></h3><table tabindex="0"><thead><tr><th>情况</th><th>阶段</th><th>错误码</th><th>客户端动作</th></tr></thead><tbody><tr><td>未携带令牌</td><td>Authorize</td><td><code>SECURITY_DENIED_001</code>（401）</td><td>刷新一次，失败则返回登录页</td></tr><tr><td>令牌过期 / 签名不符</td><td>Authenticate</td><td><code>SECURITY_DENIED_003</code>（401）</td><td>刷新一次并重放</td></tr><tr><td>会话被吊销</td><td>Authenticate（会话门禁）</td><td><code>IDENTITY_DENIED_001</code></td><td>返回登录页</td></tr><tr><td>已锁定</td><td>Authenticate（会话门禁）</td><td><code>IDENTITY_DENIED_002</code></td><td>按 <code>details.reason</code> 显示锁屏或强制改密</td></tr><tr><td>没有权限码 / 被 Deny / 套餐不含</td><td>Authorize</td><td><code>SECURITY_DENIED_004</code>（403）</td><td>提示无权限</td></tr><tr><td>共享库升级中</td><td>ASP.NET Core（维护模式）</td><td><code>RUNTIME_UNAVAILABLE_003</code>（503）</td><td>提示稍后重试</td></tr></tbody></table><h3 id="失败调用的副作用" tabindex="-1">失败调用的副作用 <a class="header-anchor" href="#失败调用的副作用" aria-label="Permalink to “失败调用的副作用”">​</a></h3><p>调用失败时，事务回滚，仓储写入随之撤销；调用中暂存的实时推送与缓存失效按回滚处理（推送丢弃，缓存失效照常执行）。访问日志与异常日志照常记录，标注了审计的操作在操作日志中记录失败；权限变更日志与数据变更只在调用成功时记录。登录相关的事件（密码错误、验证码错误、节流拒绝、第二步验证码错误）无论成败都记入登录日志。</p><h3 id="日志写入" tabindex="-1">日志写入 <a class="header-anchor" href="#日志写入" aria-label="Permalink to “日志写入”">​</a></h3><p>所有日志只进有界队列（<code>BasicApp:Auditing:QueueCapacity</code>），由后台批量落库，写日志不改变调用结果。</p><h2 id="四、普通端点" tabindex="-1">四、普通端点 <a class="header-anchor" href="#四、普通端点" aria-label="Permalink to “四、普通端点”">​</a></h2><p>上传、下载、头像等普通端点不属于操作，但仍通过 <code>RequireXiHanPermission(...)</code> / <code>RequireXiHanAuthentication()</code> 经过内核的认证与授权；宿主的端点过滤器在端点执行时登记端点身份与实际状态码，访问日志与数据变更按 <code>files.upload</code> 这类名字记录，写入类端点另进操作日志。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./authentication">统一认证</a> · <a href="./permission">权限管理</a> · <a href="./access-policy">访问策略与权限条件</a> · <a href="./logging">日志审计</a></li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};